--   Director: Charles DeLaTorre -- appointed 2022-12-01 (month)
--   Director: Domingo Sauceda -- appointed 2022-12-01 (month)
--   Director: Anagh Mamdapurkar -- appointed 2022-12-01 (month)
--   Director: Larry Taylor -- appointed 2024-12-01 (month)
--   Director: Camelia Vera -- appointed 2025-01-14 (day)
-- Valley County Water District (at large, 5 seats; RR/CC DST CW VA; https://vcwd.org/101/Board-of-Directors):
--   Director: David L. Muse -- appointed 2022-12-01 (month)
--   Director: Jazmin Leos -- appointed 2022-12-01 (month)
--   Director: Lenet Pacheco -- appointed 2022-12-01 (month)
--   Director: Ralph Galvan -- appointed 2024-12-01 (month)
--   Director: Javier E. Vargas -- appointed 2024-12-01 (month)
--
-- BATCH NOTES:
--   All 8 boards are 5 directors elected AT LARGE. Seat counts come from matching RR/CC Nov 2022 / Nov 2024 winners and
--     filers to the Nov 2026 list (3 seats in the 2022 cycle, 2 in 2024; La Habra Heights 2 and 3); Quartz Hill and Valley
--     County print term dates that agree.
--   ON THE BALLOT (3 races / 15 candidates): Crescenta Valley (3 seats, 4 candidates; Kerry Erickson did not file), La
--     Puente Valley (3 seats, 6 candidates), Valley County (3 seats, 5 candidates). Each at-large race is bound to one of
--     the three seats up (races are unique per election+office).
--   APPOINTED IN LIEU (candidates <= seats, no race): Green Valley (3 regular + 1 special to Dec 1 2028: Garth), La
--     Habra Heights (2), Orchard Dale (3), Quartz Hill (3), San Gabriel CWD (3 regular + 1 special to Dec 1 2028: Vera).
--     No notice of no election found for these; basis = filed-candidate count after the 8/12/2026 extended filing
--     deadline.
--   GREEN VALLEY: the district site is stale (still lists Jon Coon; minutes stop Sept 2024). Mark Christiansen is seated
--     from the RR/CC Nov 2026 list, which flags him as the incumbent; his appointment date is unknown (term_start NULL,
--     precision unknown).
--   REUSED ROW: David E. Argudo (his 2026 LA County Supervisor D1 candidate row -- same La Puente person).
BEGIN;

-- ─── 1. Government + governing board (chamber) per special district (none existed) ─────────
INSERT INTO essentials.governments (id, name, type, state)
SELECT v.id, v.name, 'LOCAL', 'CA'
  FROM (VALUES
    ('825046ce-85b7-5320-9877-49a9e30b07ce'::uuid, 'Crescenta Valley Water District, California, US'),
    ('5646bc9c-b556-5547-8dba-b527886f32a5'::uuid, 'Green Valley County Water District, California, US'),
    ('a98c97fc-859b-5f41-9fa6-5d427d9f60be'::uuid, 'La Habra Heights County Water District, California, US'),
    ('0c20ab89-3589-5a8a-8cd1-f29edd0ffc13'::uuid, 'La Puente Valley County Water District, California, US'),
    ('0309ca3c-5ced-5cce-85d6-b4ca66d147b8'::uuid, 'Orchard Dale Water District, California, US'),
    ('94bfcf97-b1d3-5f81-8b9e-97f83e1ab965'::uuid, 'Quartz Hill Water District, California, US'),
    ('bb81ebf1-69fa-5c6a-ab78-ecf9040dacdc'::uuid, 'San Gabriel County Water District, California, US'),
    ('6601972a-80af-56e9-abf3-0fd716bca36a'::uuid, 'Valley County Water District, California, US')
  ) AS v(id, name)
 WHERE NOT EXISTS (SELECT 1 FROM essentials.governments g WHERE g.id = v.id);

