-- ─── 8. Post-verify gate ──────────────────────────────────────────────────────────────────
DO $$
DECLARE n int; n2 int;
BEGIN
  SELECT count(*) INTO n FROM essentials.geofence_boundaries gb
   WHERE gb.mtfcc = 'X-CA-SPD' AND gb.geo_id IN (SELECT d.geo_id FROM essentials.districts d WHERE d.government_id IN ('825046ce-85b7-5320-9877-49a9e30b07ce'::uuid, '5646bc9c-b556-5547-8dba-b527886f32a5'::uuid, 'a98c97fc-859b-5f41-9fa6-5d427d9f60be'::uuid, '0c20ab89-3589-5a8a-8cd1-f29edd0ffc13'::uuid, '0309ca3c-5ced-5cce-85d6-b4ca66d147b8'::uuid, '94bfcf97-b1d3-5f81-8b9e-97f83e1ab965'::uuid, 'bb81ebf1-69fa-5c6a-ab78-ecf9040dacdc'::uuid, '6601972a-80af-56e9-abf3-0fd716bca36a'::uuid))
     AND public.ST_IsValid(gb.geometry) AND NOT public.ST_IsEmpty(gb.geometry) AND public.ST_SRID(gb.geometry) = 4326;
  IF n <> 8 THEN RAISE EXCEPTION 'expected 8 valid polygons, got %', n; END IF;

  SELECT count(*) INTO n FROM essentials.districts d WHERE d.government_id IN ('825046ce-85b7-5320-9877-49a9e30b07ce'::uuid, '5646bc9c-b556-5547-8dba-b527886f32a5'::uuid, 'a98c97fc-859b-5f41-9fa6-5d427d9f60be'::uuid, '0c20ab89-3589-5a8a-8cd1-f29edd0ffc13'::uuid, '0309ca3c-5ced-5cce-85d6-b4ca66d147b8'::uuid, '94bfcf97-b1d3-5f81-8b9e-97f83e1ab965'::uuid, 'bb81ebf1-69fa-5c6a-ab78-ecf9040dacdc'::uuid, '6601972a-80af-56e9-abf3-0fd716bca36a'::uuid) AND d.district_type = 'LOCAL' AND d.mtfcc = 'X-CA-SPD';
  IF n <> 8 THEN RAISE EXCEPTION 'expected 8 LOCAL districts, got %', n; END IF;

  SELECT count(*) INTO n FROM essentials.offices o JOIN essentials.districts d ON d.id = o.district_id WHERE d.government_id IN ('825046ce-85b7-5320-9877-49a9e30b07ce'::uuid, '5646bc9c-b556-5547-8dba-b527886f32a5'::uuid, 'a98c97fc-859b-5f41-9fa6-5d427d9f60be'::uuid, '0c20ab89-3589-5a8a-8cd1-f29edd0ffc13'::uuid, '0309ca3c-5ced-5cce-85d6-b4ca66d147b8'::uuid, '94bfcf97-b1d3-5f81-8b9e-97f83e1ab965'::uuid, 'bb81ebf1-69fa-5c6a-ab78-ecf9040dacdc'::uuid, '6601972a-80af-56e9-abf3-0fd716bca36a'::uuid);
  IF n <> 40 THEN RAISE EXCEPTION 'expected 40 offices, got %', n; END IF;

  -- every held seat is held by exactly the director named for it (office_current_holder = query-time occupant)
  SELECT count(*) INTO n FROM (VALUES ('519c3143-2ec7-5c52-8780-8c999dbd5003'::uuid, 'c950eeaa-9fb9-589b-85ab-0b712388d308'::uuid), ('e45f0e89-6bc5-5416-84b7-92f78ce3cd99'::uuid, 'eba3e605-1284-58a0-b082-72ffccb63778'::uuid), ('2709a8c4-5af1-5dcf-bbe2-bff6032da2fd'::uuid, '22607bbb-2936-51d5-bac7-194f6ccbc1e4'::uuid), ('1523a4b0-3b86-53b7-ae0e-48ec2121b876'::uuid, '181e7eb5-e831-595a-8bbd-f174e9c4e43f'::uuid), ('dff280a1-6c34-567a-acbe-cb487970d6a3'::uuid, 'a016b00f-a620-5fcf-b825-9679ca15deff'::uuid), ('690f33fd-07a9-5e7c-9225-efe88eed7b42'::uuid, 'e2474b89-e0fd-578f-bc16-c2fd9930550a'::uuid), ('d5798bbb-cae9-5663-a309-98310e422ec2'::uuid, 'b446c42f-82e7-5489-9141-33a22631226f'::uuid), ('b972a16e-e5a2-57b0-a3df-cfc709a06ecd'::uuid, '785881b2-eb08-54bf-9103-cfe1a888b423'::uuid), ('e643e8f4-ad91-5216-affb-3242300814f0'::uuid, 'ce0e6df0-7778-5804-b8b7-3a8bb6d07cc1'::uuid), ('1984d028-4ce2-53cd-98c4-e42248b585fb'::uuid, 'ccece634-ffe5-5afa-b1fb-39c9651b6539'::uuid), ('07a06f93-d93a-5bc7-b6de-a6334e0897da'::uuid, '6e9bfef1-25fe-59e8-a3ab-c7f61cffc60d'::uuid), ('1682503b-6628-51f4-9287-6bca588f16fe'::uuid, '217722b4-55b3-5a6f-b83b-f53d827099b7'::uuid), ('1f4d8f1f-710b-5fc6-82ae-d14752ccb344'::uuid, '103c3da4-610f-5ce6-abe9-0055b947b542'::uuid), ('8bdc891c-bd6a-5b58-ae98-1c725b1b3516'::uuid, '02a2bd53-3d9c-51b9-89f1-c40f242a0d51'::uuid), ('23d61f5b-3ca9-5076-92ab-024f6fc152e6'::uuid, 'bd36b16c-9973-5830-8400-39eb548fea1a'::uuid), ('cb80e8ac-88b7-5a9c-9d5e-53218aef06ce'::uuid, '6e738bc6-1f71-545e-8165-382c62744fbd'::uuid), ('2ee0fe8c-eda9-565d-b701-6cb82e9d58cd'::uuid, 'cc0e68aa-78fe-5193-88fb-ddb38be62777'::uuid), ('51a2d7a8-bd86-54e4-8ec6-190d081d7825'::uuid, '22ea3a62-c0dc-59cf-b532-729222cd5bcd'::uuid), ('58e97143-61ef-53f0-b8f2-0bc00cbc4268'::uuid, '95860909-eb07-4ed4-bea1-54081d92ce8d'::uuid), ('d6c4ef79-f41e-53b7-8620-a6317f9f5c1d'::uuid, 'dcb3d1e2-8206-594c-a17c-bffbbc155eab'::uuid), ('d5703bbe-6260-56ec-8fee-0d7554eb2ee6'::uuid, 'a610ed2d-2ad1-57b3-9244-8ee2a8115521'::uuid), ('dcdeeb09-282a-5c26-982d-620f442a416e'::uuid, 'cfcdcd48-b858-5514-b450-ca03da398e14'::uuid), ('562add0d-ae52-5f50-816a-9096bbfc8cc5'::uuid, '8440be8a-43ed-5ce0-bd6c-ee15080e2235'::uuid), ('b4024aad-5ee3-548e-bb60-651ed1743e3f'::uuid, 'af4ca5f5-642f-5097-95cc-aaebfff3bbdb'::uuid), ('f9553b6d-68c8-55a2-a4f1-fe90a5e2c62a'::uuid, 'f2bb89a4-99e3-591b-9e2f-35c046b1aae0'::uuid), ('68cb5cbb-d34f-5e58-b418-a1ef76f111d5'::uuid, 'de06e41b-ddc2-5d9e-8832-1d92ecf184a8'::uuid), ('9bdeb46b-1b02-5056-adf9-6a81a3324289'::uuid, 'c1c1ff41-7ada-56d6-9078-f5f1e906b6e4'::uuid), ('84815b94-c5ea-5735-9a22-9a58f2df20b9'::uuid, '811f3409-b765-52a1-8431-c6b515b25caa'::uuid), ('ed208c34-6374-515e-a28b-645827ec378d'::uuid, 'c9339251-71e4-554b-8cf6-12fd7f67c101'::uuid), ('aa2199d0-f32e-500f-af5e-4f71f93fcb49'::uuid, '61aa82e4-16e1-5b7b-90b4-e2bf80b01636'::uuid), ('303b26e4-ca9b-5c9e-a634-79744e8fede8'::uuid, '0c7912f3-b922-575a-96c5-58aebdf20252'::uuid), ('5b3dcb45-b424-5983-a756-77ab380971ff'::uuid, '499bc369-6468-5977-9f67-6520755ad9f2'::uuid), ('15a075f7-de9f-58d3-8786-dc829a36c64e'::uuid, '44a7497f-304e-5c0f-a6bd-c281a4700139'::uuid), ('b4864727-233c-5749-a882-7921bffeced4'::uuid, '4847d597-00ce-512c-81ec-ae870a17a265'::uuid), ('a273cc82-786e-5d71-a1d2-f8a490c9966d'::uuid, '6692d1eb-fdcb-59d4-9f6b-71f4de387bf5'::uuid), ('9307fb86-a1f3-56ba-a114-a750437335ec'::uuid, '62b019e0-eac0-5cce-8ec2-002e596b9b1b'::uuid), ('fd709065-c549-5c4b-93db-017ed09f90ff'::uuid, 'f4550d05-abc9-5ac7-86b0-f6ccce289787'::uuid), ('85d6eb45-70bc-5f55-a5a6-610c9ac31d52'::uuid, 'a035c666-48cc-5c1c-8855-8d50cbd3328d'::uuid), ('2762ee92-23c1-5f96-ab7f-0b2c118af551'::uuid, 'ae620aae-a1e0-563d-8491-a8716b092c3b'::uuid), ('3528c5ed-7b5a-540b-a6db-038646945d32'::uuid, 'fc489e94-38a4-5a79-a094-e13a96379781'::uuid)) AS v(oid, pid)
    JOIN essentials.office_current_holder och ON och.office_id = v.oid AND och.politician_id = v.pid;
  IF n <> 40 THEN RAISE EXCEPTION 'expected 40 seats each held by its named director, got %', n; END IF;

  SELECT count(*) INTO n FROM (VALUES ('519c3143-2ec7-5c52-8780-8c999dbd5003'::uuid, 'c950eeaa-9fb9-589b-85ab-0b712388d308'::uuid), ('e45f0e89-6bc5-5416-84b7-92f78ce3cd99'::uuid, 'eba3e605-1284-58a0-b082-72ffccb63778'::uuid), ('2709a8c4-5af1-5dcf-bbe2-bff6032da2fd'::uuid, '22607bbb-2936-51d5-bac7-194f6ccbc1e4'::uuid), ('1523a4b0-3b86-53b7-ae0e-48ec2121b876'::uuid, '181e7eb5-e831-595a-8bbd-f174e9c4e43f'::uuid), ('dff280a1-6c34-567a-acbe-cb487970d6a3'::uuid, 'a016b00f-a620-5fcf-b825-9679ca15deff'::uuid), ('690f33fd-07a9-5e7c-9225-efe88eed7b42'::uuid, 'e2474b89-e0fd-578f-bc16-c2fd9930550a'::uuid), ('d5798bbb-cae9-5663-a309-98310e422ec2'::uuid, 'b446c42f-82e7-5489-9141-33a22631226f'::uuid), ('b972a16e-e5a2-57b0-a3df-cfc709a06ecd'::uuid, '785881b2-eb08-54bf-9103-cfe1a888b423'::uuid), ('e643e8f4-ad91-5216-affb-3242300814f0'::uuid, 'ce0e6df0-7778-5804-b8b7-3a8bb6d07cc1'::uuid), ('1984d028-4ce2-53cd-98c4-e42248b585fb'::uuid, 'ccece634-ffe5-5afa-b1fb-39c9651b6539'::uuid), ('07a06f93-d93a-5bc7-b6de-a6334e0897da'::uuid, '6e9bfef1-25fe-59e8-a3ab-c7f61cffc60d'::uuid), ('1682503b-6628-51f4-9287-6bca588f16fe'::uuid, '217722b4-55b3-5a6f-b83b-f53d827099b7'::uuid), ('1f4d8f1f-710b-5fc6-82ae-d14752ccb344'::uuid, '103c3da4-610f-5ce6-abe9-0055b947b542'::uuid), ('8bdc891c-bd6a-5b58-ae98-1c725b1b3516'::uuid, '02a2bd53-3d9c-51b9-89f1-c40f242a0d51'::uuid), ('23d61f5b-3ca9-5076-92ab-024f6fc152e6'::uuid, 'bd36b16c-9973-5830-8400-39eb548fea1a'::uuid), ('cb80e8ac-88b7-5a9c-9d5e-53218aef06ce'::uuid, '6e738bc6-1f71-545e-8165-382c62744fbd'::uuid), ('2ee0fe8c-eda9-565d-b701-6cb82e9d58cd'::uuid, 'cc0e68aa-78fe-5193-88fb-ddb38be62777'::uuid), ('51a2d7a8-bd86-54e4-8ec6-190d081d7825'::uuid, '22ea3a62-c0dc-59cf-b532-729222cd5bcd'::uuid), ('58e97143-61ef-53f0-b8f2-0bc00cbc4268'::uuid, '95860909-eb07-4ed4-bea1-54081d92ce8d'::uuid), ('d6c4ef79-f41e-53b7-8620-a6317f9f5c1d'::uuid, 'dcb3d1e2-8206-594c-a17c-bffbbc155eab'::uuid), ('d5703bbe-6260-56ec-8fee-0d7554eb2ee6'::uuid, 'a610ed2d-2ad1-57b3-9244-8ee2a8115521'::uuid), ('dcdeeb09-282a-5c26-982d-620f442a416e'::uuid, 'cfcdcd48-b858-5514-b450-ca03da398e14'::uuid), ('562add0d-ae52-5f50-816a-9096bbfc8cc5'::uuid, '8440be8a-43ed-5ce0-bd6c-ee15080e2235'::uuid), ('b4024aad-5ee3-548e-bb60-651ed1743e3f'::uuid, 'af4ca5f5-642f-5097-95cc-aaebfff3bbdb'::uuid), ('f9553b6d-68c8-55a2-a4f1-fe90a5e2c62a'::uuid, 'f2bb89a4-99e3-591b-9e2f-35c046b1aae0'::uuid), ('68cb5cbb-d34f-5e58-b418-a1ef76f111d5'::uuid, 'de06e41b-ddc2-5d9e-8832-1d92ecf184a8'::uuid), ('9bdeb46b-1b02-5056-adf9-6a81a3324289'::uuid, 'c1c1ff41-7ada-56d6-9078-f5f1e906b6e4'::uuid), ('84815b94-c5ea-5735-9a22-9a58f2df20b9'::uuid, '811f3409-b765-52a1-8431-c6b515b25caa'::uuid), ('ed208c34-6374-515e-a28b-645827ec378d'::uuid, 'c9339251-71e4-554b-8cf6-12fd7f67c101'::uuid), ('aa2199d0-f32e-500f-af5e-4f71f93fcb49'::uuid, '61aa82e4-16e1-5b7b-90b4-e2bf80b01636'::uuid), ('303b26e4-ca9b-5c9e-a634-79744e8fede8'::uuid, '0c7912f3-b922-575a-96c5-58aebdf20252'::uuid), ('5b3dcb45-b424-5983-a756-77ab380971ff'::uuid, '499bc369-6468-5977-9f67-6520755ad9f2'::uuid), ('15a075f7-de9f-58d3-8786-dc829a36c64e'::uuid, '44a7497f-304e-5c0f-a6bd-c281a4700139'::uuid), ('b4864727-233c-5749-a882-7921bffeced4'::uuid, '4847d597-00ce-512c-81ec-ae870a17a265'::uuid), ('a273cc82-786e-5d71-a1d2-f8a490c9966d'::uuid, '6692d1eb-fdcb-59d4-9f6b-71f4de387bf5'::uuid), ('9307fb86-a1f3-56ba-a114-a750437335ec'::uuid, '62b019e0-eac0-5cce-8ec2-002e596b9b1b'::uuid), ('fd709065-c549-5c4b-93db-017ed09f90ff'::uuid, 'f4550d05-abc9-5ac7-86b0-f6ccce289787'::uuid), ('85d6eb45-70bc-5f55-a5a6-610c9ac31d52'::uuid, 'a035c666-48cc-5c1c-8855-8d50cbd3328d'::uuid), ('2762ee92-23c1-5f96-ab7f-0b2c118af551'::uuid, 'ae620aae-a1e0-563d-8491-a8716b092c3b'::uuid), ('3528c5ed-7b5a-540b-a6db-038646945d32'::uuid, 'fc489e94-38a4-5a79-a094-e13a96379781'::uuid)) AS v(oid, pid) JOIN essentials.politicians p ON p.id = v.pid
   WHERE p.party IS NOT NULL OR NOT p.is_active OR NOT p.is_incumbent;
  IF n <> 0 THEN RAISE EXCEPTION '% seated director row(s) carry a party or are not active incumbents', n; END IF;

  -- partition: no two divisions of one district overlap beyond ~1,000 m2 (1e-7 deg2 at 34 N; planar, decision 0006)
  SELECT count(*) INTO n FROM essentials.districts a JOIN essentials.districts c ON c.government_id = a.government_id AND a.geo_id < c.geo_id
    JOIN essentials.geofence_boundaries ga ON ga.geo_id = a.geo_id AND ga.mtfcc = 'X-CA-SPD'
    JOIN essentials.geofence_boundaries gc ON gc.geo_id = c.geo_id AND gc.mtfcc = 'X-CA-SPD'
   WHERE a.government_id IN ('825046ce-85b7-5320-9877-49a9e30b07ce'::uuid, '5646bc9c-b556-5547-8dba-b527886f32a5'::uuid, 'a98c97fc-859b-5f41-9fa6-5d427d9f60be'::uuid, '0c20ab89-3589-5a8a-8cd1-f29edd0ffc13'::uuid, '0309ca3c-5ced-5cce-85d6-b4ca66d147b8'::uuid, '94bfcf97-b1d3-5f81-8b9e-97f83e1ab965'::uuid, 'bb81ebf1-69fa-5c6a-ab78-ecf9040dacdc'::uuid, '6601972a-80af-56e9-abf3-0fd716bca36a'::uuid) AND public.ST_Area(public.ST_Intersection(ga.geometry, gc.geometry)) > 1e-7;
  IF n <> 0 THEN RAISE EXCEPTION '% division pair(s) overlap', n; END IF;

  -- END TO END: an interior point of each polygon resolves (geofence -> LOCAL district -> office -> holder)
  -- to exactly that district's own director(s) among this board's seats
  SELECT count(*) INTO n FROM essentials.districts me
    JOIN essentials.geofence_boundaries mg ON mg.geo_id = me.geo_id AND mg.mtfcc = 'X-CA-SPD'
   WHERE me.government_id IN ('825046ce-85b7-5320-9877-49a9e30b07ce'::uuid, '5646bc9c-b556-5547-8dba-b527886f32a5'::uuid, 'a98c97fc-859b-5f41-9fa6-5d427d9f60be'::uuid, '0c20ab89-3589-5a8a-8cd1-f29edd0ffc13'::uuid, '0309ca3c-5ced-5cce-85d6-b4ca66d147b8'::uuid, '94bfcf97-b1d3-5f81-8b9e-97f83e1ab965'::uuid, 'bb81ebf1-69fa-5c6a-ab78-ecf9040dacdc'::uuid, '6601972a-80af-56e9-abf3-0fd716bca36a'::uuid)
     AND (SELECT string_agg(och.politician_id::text, ',' ORDER BY och.politician_id)
            FROM essentials.geofence_boundaries gb
            JOIN essentials.districts d ON d.geo_id = gb.geo_id AND d.district_type = 'LOCAL' AND d.mtfcc = gb.mtfcc
            JOIN essentials.offices o ON o.district_id = d.id
            JOIN essentials.office_current_holder och ON och.office_id = o.id AND och.politician_id IS NOT NULL
           WHERE d.government_id = me.government_id AND gb.mtfcc = 'X-CA-SPD'
             AND public.ST_Covers(gb.geometry, public.ST_PointOnSurface(mg.geometry)))
         IS DISTINCT FROM
         (SELECT string_agg(och.politician_id::text, ',' ORDER BY och.politician_id)
            FROM essentials.offices o JOIN essentials.office_current_holder och ON och.office_id = o.id
           WHERE o.district_id = me.id AND och.politician_id IS NOT NULL);
  IF n <> 0 THEN RAISE EXCEPTION '% polygon(s) do not return exactly their own director(s) at an interior point', n; END IF;

  SELECT count(*), count(*) FILTER (WHERE r.office_id IS NULL OR r.primary_party IS NOT NULL) INTO n, n2
    FROM essentials.races r JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND d.government_id IN ('825046ce-85b7-5320-9877-49a9e30b07ce'::uuid, '5646bc9c-b556-5547-8dba-b527886f32a5'::uuid, 'a98c97fc-859b-5f41-9fa6-5d427d9f60be'::uuid, '0c20ab89-3589-5a8a-8cd1-f29edd0ffc13'::uuid, '0309ca3c-5ced-5cce-85d6-b4ca66d147b8'::uuid, '94bfcf97-b1d3-5f81-8b9e-97f83e1ab965'::uuid, 'bb81ebf1-69fa-5c6a-ab78-ecf9040dacdc'::uuid, '6601972a-80af-56e9-abf3-0fd716bca36a'::uuid);
  IF n <> 3 OR n2 <> 0 THEN RAISE EXCEPTION 'expected 3 office-bound nonpartisan races, got % (% bad)', n, n2; END IF;
  SELECT count(*) INTO n FROM essentials.race_candidates rc JOIN essentials.races r ON r.id = rc.race_id
    JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND d.government_id IN ('825046ce-85b7-5320-9877-49a9e30b07ce'::uuid, '5646bc9c-b556-5547-8dba-b527886f32a5'::uuid, 'a98c97fc-859b-5f41-9fa6-5d427d9f60be'::uuid, '0c20ab89-3589-5a8a-8cd1-f29edd0ffc13'::uuid, '0309ca3c-5ced-5cce-85d6-b4ca66d147b8'::uuid, '94bfcf97-b1d3-5f81-8b9e-97f83e1ab965'::uuid, 'bb81ebf1-69fa-5c6a-ab78-ecf9040dacdc'::uuid, '6601972a-80af-56e9-abf3-0fd716bca36a'::uuid);
  IF n <> 15 THEN RAISE EXCEPTION 'expected 15 candidates, got %', n; END IF;

  -- every incumbent candidate is linked to a director seated on this board
  SELECT count(*) INTO n FROM essentials.race_candidates rc JOIN essentials.races r ON r.id = rc.race_id
    JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND d.government_id IN ('825046ce-85b7-5320-9877-49a9e30b07ce'::uuid, '5646bc9c-b556-5547-8dba-b527886f32a5'::uuid, 'a98c97fc-859b-5f41-9fa6-5d427d9f60be'::uuid, '0c20ab89-3589-5a8a-8cd1-f29edd0ffc13'::uuid, '0309ca3c-5ced-5cce-85d6-b4ca66d147b8'::uuid, '94bfcf97-b1d3-5f81-8b9e-97f83e1ab965'::uuid, 'bb81ebf1-69fa-5c6a-ab78-ecf9040dacdc'::uuid, '6601972a-80af-56e9-abf3-0fd716bca36a'::uuid) AND rc.is_incumbent
     AND NOT EXISTS (SELECT 1 FROM essentials.offices o2 JOIN essentials.districts d2 ON d2.id = o2.district_id
                       JOIN essentials.office_current_holder och ON och.office_id = o2.id
                      WHERE d2.government_id = d.government_id AND och.politician_id = rc.politician_id);
  IF n <> 0 THEN RAISE EXCEPTION '% incumbent candidate(s) not linked to a seated director', n; END IF;

  RAISE NOTICE 'CA_0242 applied: 8 boards, 8 polygons, 40 seats (40 held), 3 races, 15 candidates';
END $$;

